import json,os,numpy as np
os.makedirs('models',exist_ok=True)
common_data="Training stage: `data/train.csv`, all thirteen trajectories and all rows after the first row of each trajectory, with each initial logged pair `y`, `x1` used only as an initial condition. Final stage: the same rows plus `data/val.csv`, all three trajectories and all rows after their first rows. No test data were available or used. There are 4698 scored time samples across the two supplied files. Rows were equally weighted to match sample-wise output scoring; derivative columns were used in structural exploration but not in these final objectives. All listed trajectories were retained to test different cold-start conditions. Exact suffix overlaps were found: training trajectories 8 and 11 reproduce validation trajectory 1 from row 309 and validation trajectory 2 from row 209 respectively (zero-based row indices); training trajectories 9, 10, 12 and 13 reproduce training trajectories 1, 2, 3 and 4 from rows 309, 309, 209 and 209. Thus file-level validation is not an independent-experiment holdout. The final use of validation is explicit and its final error is in-sample."
common_criterion="Sum of squared free-running output errors in `y`, excluding the initial row of each trajectory. Each rollout uses classical fourth-order Runge-Kutta at the supplied sampling period `0.01` s and holds `x2` constant within a sample. Simulated states are never reset to subsequent measurements. The training-only stage and final joint stage use the same criterion, because integrated output accuracy, rather than sampled derivative accuracy, is the requested use. The expression `dy = x1` is assumed from the essentially exact central-difference relation observed on interior rows and is not fitted."
common_limit="The physical system, units, measurement process, intended use and meaning of `x2` are not supplied. Numerical coefficients refer to the logged scales, not identified physical constants. Trigonometric arguments assume the numerical `y` coordinate is suitable for a dimensionless angle-like representation; no physical angle unit is asserted. The logged `x1` and `dx1` equal central finite differences of `y` and `x1` on interior rows, to numerical precision, and are quantized, so instantaneous derivatives are not independently measured. Identification cannot separate all measurement and dynamic effects. The observed training domain is approximately `-2.5133 <= y <= 2.5353`, `-20.1062 <= x1 <= 14.4513`, `-4.9452 <= x2 <= 3.9526`, all in unspecified logged units. Extrapolation outside this domain or beyond the supplied trajectory lengths is unvalidated. There are experiment-dependent residuals, notably validation trajectory 1, and exact train/validation suffix overlaps; neither file-level validation nor the final combined fit is a pristine independent test."

def param(name,val,desc,typ='fitted',eq=None):
 z={'name':name,'value':float(val),'unit':'not supplied','type':typ,'description':desc+' Its value is on the supplied logged scale; physical units are not stated.'}
 if eq is not None:z['equation']=eq
 return z

def methods(label,fam,start0,code,extra):
 r=json.load(open('results/final_'+label+'.json'))
 return ("Bounded nonlinear least squares, using the trust-region-reflective algorithm in `scipy.optimize.least_squares` (SciPy 1.18.1). This is direct output-error system identification: integration makes the objective nonlinear in all coefficients, so ordinary least squares cannot solve it. All fitted coefficients were optimized jointly in each of two stages. "+extra+" The training-only numeric starting vector in the coefficient order of the parameter rows was `"+str(start0)+"`, on the logged parameter scales (physical units unknown). These rounded exploratory starting values place the restoring strength, input gain and friction near the derivative-regression scale and avoid an unstable initial rollout. The final joint starting vector was the training-only estimate `"+str(r['start'])+"`, on those same scales, so it was warm-started rather than restarted randomly. The final bounds in this coefficient order were `"+str(r['bounds'])+"`, on those same scales. Positive damping, restoring strength and friction were bounded to select a dissipative model; wide remaining bounds limit poorly supported extrapolation. "+code+" Both stages used `diff_step = 0.0001`, `x_scale = 'jac'`, `ftol = 1e-7`, `xtol = 1e-7`, `gtol = 1e-6`; these dimensionless optimizer settings were chosen for a reproducible local fit without demanding more precision than the logged resolution. Training evaluations were capped at `max_nfev = 140` for the trigonometric models and `max_nfev = 180` for the polynomial model; the final cap was `max_nfev = 180`. Two-point finite-difference Jacobians were used. No random search or random numbers were used; no seed applies. Bounds and starts are also recorded in `results/`. The optimizer is local and global optimality is not claimed. Method reference: T. F. Coleman and Y. Li, An Interior Trust Region Approach for Nonlinear Minimization Subject to Bounds, SIAM Journal on Optimization (1996), cited from memory without successful source verification. `final_fit.py` reproduces the final estimates from the saved training-only results; the cited stage scripts reproduce those warm starts.")

def diagnostics(label):
 r=json.load(open('results/final_'+label+'.json'));rr=json.load(open('results/residuals.json'))[label]
 return ("Before the final joint refit, sample-weighted free-running `y` RMSE was `"+format(r['pre_refit_train_rmse'],'.8f')+"` on training and `"+format(r['pre_refit_val_rmse'],'.8f')+"` on validation, in unspecified `y` units. After the final refit these were `"+format(r['train_rmse'],'.8f')+"` and `"+format(r['val_rmse'],'.8f')+"` respectively, now both in-sample. Diagnostics in `residuals.py` compare sampled `dx1` residuals and free-running output residuals. Sampled derivative RMSE was `"+format(rr['train']['derivative_rmse'],'.6f')+"` on training and `"+format(rr['val']['derivative_rmse'],'.6f')+"` on validation, in unspecified derivative units. The final validation per-trajectory output RMSE vector was `"+str(r['val_per_traj'])+"` in unspecified `y` units. These diagnostics are not test results.")

for label in ['TrigSmooth','ForceClamp','Polynomial']:
 r=json.load(open('results/final_'+label+'.json'));p=r['p']
 if label!='Polynomial':
  names=['bias','gain','damp','stiff','fric','width','asym','fricSin','fricCos']
  descriptions=['Constant acceleration offset `bias`.','Input coefficient of `gain*x2`.','Linear velocity damping coefficient of `-damp*x1`.','Restoring coefficient of `-stiff*sin(y)`.','Baseline velocity-resistance amplitude `fric`.','Velocity scale `width` in `atan(x1/width)`.' if label=='TrigSmooth' else 'Near-rest force/velocity slope `width` in `width*x1`.','Even restoring correction coefficient of `asym*(cos(y)-1)`.','Odd modulation coefficient `fricSin` in `fricSin*sin(y)`.','Even modulation coefficient `fricCos` in `fricCos*(cos(y)-1)`.']
  parameters=[param(n,v,d) for n,v,d in zip(names,p,descriptions)]
  drive='bias+gain*x2-stiff*sin(y)+asym*(cos(y)-1)';F='fric+fricSin*sin(y)+fricCos*(cos(y)-1)'
  if label=='TrigSmooth':
   expression=drive+'-damp*x1-('+F+')*(2/pi)*atan(x1/width)'
   family="Nonlinear trigonometric state-space oscillator with a regularized Coulomb-type velocity resistance. The arctangent is a bounded odd regularization, not an asserted microscopic friction law. This structure was chosen empirically; no particular physical mechanism is supplied by the task."
   interpretation="`dy = x1` makes `x1` the velocity-like coordinate of `y`. The sum `bias+gain*x2-stiff*sin(y)+asym*(cos(y)-1)` is a velocity-independent drive: `bias` shifts it, `gain*x2` is linear input coupling, `-stiff*sin(y)` provides a bounded restoring effect near the origin, and `asym*(cos(y)-1)` permits different restoring forces at positive and negative coordinates. The amplitude `fric+fricSin*sin(y)+fricCos*(cos(y)-1)` varies the velocity resistance with the first state; it is positive over all numerical angles at this fit. `-damp*x1` gives linear damping. The term `-(fric+fricSin*sin(y)+fricCos*(cos(y)-1))*(2/pi)*atan(x1/width)` opposes velocity, is approximately linear near zero velocity, and saturates at large velocity. These are mathematical effects, not identified physical components."
   origin="I began with affine, sine and cubic restoring equations fitted against sampled `dx1`. Sine and cubic terms outperformed affine restoring terms, and adding sign or smooth saturating velocity resistance improved free-running predictions. Residuals of the simple sine-plus-friction form differed between positive and negative large `y`, motivating the empirically proposed `asym*(cos(y)-1)` and the modulation `fricSin*sin(y)+fricCos*(cos(y)-1)`. These basis terms were manually proposed and fitted, not discovered by genetic programming. Comparing arctangent and hyperbolic-tangent regularizations by training-only fits and validation rollouts favored this arctangent candidate. Added angle-dependent linear damping and `x1*Abs(x1)` damping had little validation benefit and were not retained. A force-clipped alternative was also tried to address stationary residuals; it is submitted as a separate family. "+diagnostics(label)
   limitations=common_limit+" The smooth friction has no true sticking interval: eventually it can drift away from a nonzero logged rest coordinate. Derivative residual means remain nonzero near rest and at positive small `y`. Its lower velocity-scale bound is active, so the data do not robustly determine the detailed transition around zero velocity. The width bound was chosen to avoid an excessively stiff sampled rollout rather than to encode a known material property."
   method=methods(label,r['family'],r['start'] if False else [2,28,1.8,110,20,.2,0,0,0],"The training-only script is `extend_fit.py sin_atan_cos_fsin_fcos`; the force law and RK4 objective are implemented in `extend_fit.py` and `fit_models.py`.","The initial derivative regressions guided the numerical scale only; no coefficient from those regressions was fixed in the delivered model.")
  else:
   expression=drive+'-damp*x1-Min('+F+',Max(-('+F+'),'+drive+'+width*x1))'
   family="Piecewise-affine saturated-force friction coupled to a trigonometric state-space oscillator. It is a memoryless sticking/sliding approximation, related in purpose but not identical in formulation to the Karnopp friction model. Reference: D. Karnopp, Computer Simulation of Stick-Slip Friction in Mechanical Dynamic Systems, Journal of Dynamic Systems, Measurement, and Control (1985), cited from memory without successful source verification."
   interpretation="`dy = x1` defines velocity-like kinematics. Define the drive expression `bias+gain*x2-stiff*sin(y)+asym*(cos(y)-1)` and resistance bound `fric+fricSin*sin(y)+fricCos*(cos(y)-1)`, positive for all numerical angles at the fitted coefficients. Here `bias` is an acceleration offset, `gain` is input gain, `stiff` is near-origin restoring strength, and `asym` supplies even coordinate asymmetry. The terms with `fricSin` and `fricCos` empirically modulate the force bound with the coordinate. The nested `Min` and `Max` clip `bias+gain*x2-stiff*sin(y)+asym*(cos(y)-1)+width*x1` to the positive and negative resistance bounds. When unclipped, the drive cancels in `dx1` and `dx1 = -(damp+width)*x1`, so velocity tends rapidly to zero while arbitrary balanced coordinates can persist. When clipped, the model has the drive minus a saturated resistance and `damp*x1` damping. Thus it can represent sticking without an unobserved friction state. `width` is the near-rest force/velocity slope, not the velocity width used in TrigSmooth. No physical contact law is asserted."
   origin="Near-zero-velocity residuals of the smooth sine oscillator and distinct nonzero stationary coordinates motivated force-dependent cancellation at rest. I proposed the clipped affine resistance manually to allow a continuum of static equilibria; this was a structural hypothesis, not a fitted threshold from a hidden physical specification. Sine restoring terms came from comparison against affine and cubic alternatives. The cosine correction and first-state-dependent clipping limits were retained because large-coordinate and sign-asymmetric residuals decreased. The clipping operators distinguish this family from the smooth saturating family. "+diagnostics(label)+" In the final training diagnostics, sampled derivative RMSE restricted to `-0.15 <= x1 < 0.15` was `2.423418` in unspecified derivative units, versus `8.644165` for the recommended smooth candidate, but this model had worse pre-refit validation output error."
   limitations=common_limit+" Sticking locations are sensitive to parameter values and initial conditions. A memoryless clipping law cannot reproduce genuine friction hysteresis or unlogged internal states. The model improved stationary derivative residuals but validation trajectory 1 still had a substantial output bias. Its objective is nonsmooth at clipping boundaries; finite-difference local optimization may miss better parameter sets. The slope upper bound was chosen to keep near-rest decay resolvable by the specified RK4 sampling step, not from a known physical parameter."
   method=methods(label,r['family'],[2,28,1.8,110,20,100,0,0,0],"The training-only script is `extend_fit.py sin_clamp_cos_fsin_fcos`; the force law and RK4 objective are implemented in `extend_fit.py` and `fit_models.py`.","The model was fitted directly by output-error least squares because derivative-only fitting does not choose static endpoints reliably.")
 else:
  names=['bias','gain','damp','stiff','fric','width','soft','asym','fricLinear','fricQuad','floor']
  descriptions=['Constant acceleration offset `bias`.','Linear input gain `gain`.','Linear velocity damping coefficient `damp`.','Multiplier `stiff` of the polynomial restoring function.','Baseline smooth friction amplitude `fric`.','Velocity regularization scale in `tanh(x1/width)`.','Cubic softening shape coefficient `soft`.','Even restoring correction coefficient in `asym*y**2`.','Odd friction-amplitude correction in `fricLinear*y`.','Even friction-amplitude correction in `fricQuad*y**2`.','Positive shape margin `floor` used in the tied fifth-order coefficient.']
  parameters=[param(n,v,d) for n,v,d in zip(names,p,descriptions)];parameters.append(param('fifth',p[6]**2/4+p[10]**2,'Fifth-order restoring coefficient `fifth`, constrained by `fifth = soft**2/4+floor**2` to prevent a zero or negative symmetric restoring multiplier.','tied','soft**2/4+floor**2'))
  expression='bias+gain*x2-damp*x1-stiff*(y+soft*y**3+fifth*y**5)+asym*y**2-(fric+fricLinear*y+fricQuad*y**2)*tanh(x1/width)'
  family="Polynomial nonlinear state-space oscillator, a stabilized higher-order Duffing-type restoring model with smooth velocity saturation. Duffing's original cubic oscillator is described in G. Duffing, Erzwungene Schwingungen bei veraenderlicher Eigenfrequenz und ihre technische Bedeutung (1918); reference cited from memory without successful source verification. This candidate extends that mathematical family and does not assert a Duffing mechanical device."
  interpretation="`dy = x1` is velocity-like kinematics. `bias+gain*x2` adds a constant and linear input drive. `-damp*x1` is linear damping. The restoring term `-stiff*(y+soft*y**3+fifth*y**5)` contains linear attraction, cubic softening and fifth-order stabilization. With `fifth = soft**2/4+floor**2`, its factor `1+soft*y**2+fifth*y**4` remains positive for every real coordinate, unlike a pure softening cubic outside its training range. The correction `asym*y**2` allows unequal positive/negative restoring magnitudes. The positive fitted quadratic amplitude `fric+fricLinear*y+fricQuad*y**2` multiplies the bounded odd function `tanh(x1/width)` to oppose velocity; `fricLinear` and `fricQuad` allow coordinate-dependent resistance. Each coefficient is empirical, with no known physical unit or component identification."
  origin="Cubic restoring fits were substantially better than affine fits and competitive with sine fits. Rather than submit an unbounded softening cubic with spurious outside-range equilibria, I added a constrained fifth-order term; that constraint is an extrapolation safeguard chosen mathematically, not inferred as a physical law. I then used a purely polynomial first-state basis for restoring asymmetry and friction modulation, instead of the trigonometric basis used by the other candidates. `asym*y**2`, `fricLinear*y` and `fricQuad*y**2` were manually proposed to address sign-asymmetric large-coordinate residuals observed in the sine-plus-constant-friction fit. No automatic symbolic regression was run. All fitted terms were jointly estimated; their inclusion is judged by free-running output performance rather than derivative fit alone. "+diagnostics(label)
  limitations=common_limit+" This family does not assume coordinate periodicity and its high-degree restoring function grows rapidly outside the logged domain; RK4 stability outside that domain is not established. The fifth-order sign constraint is a chosen mathematical safeguard, not proof of global stability of the full asymmetric forced model. The smooth friction has no true sticking interval and can drift from logged nonzero rest coordinates. Several restoring and friction shape coefficients can trade off because trajectory coverage is limited; the velocity-scale bound is active."
  method=methods(label,r['family'],[3,28,1.6,112,20,.15,-.17,-2,-5,4,.04],"The training-only script is `fit_polynomial.py`; its starting shape uses the low-order sine expansion as a heuristic. The shape parameter bounds enforce negative cubic softening, positive fifth-order margin and nonnegative quadratic friction modulation. The width lower bound was chosen to avoid unresolved sharp friction transitions at the supplied sampling period.","The polynomial coefficient `fifth` is not independently estimated: after both fits it is computed from `soft` and `floor` by its tie equation. All other parameters were fitted jointly.")
 z={'expressions':{'dy':'x1','dx1':expression},'parameters':parameters,'estimation':{'criterion':common_criterion,'data':common_data,'method':method,'script':'final_fit.py'},'discussion':{'family':family,'interpretation':interpretation,'origin':origin,'limitations':limitations}}
 json.dump(z,open('models/'+label+'.json','w'),indent=2)
pool={'order':['TrigSmooth','Polynomial','ForceClamp'],'recommended':'TrigSmooth','reason':'Recommend the bounded trigonometric oscillator with arctangent resistance: its training-only fit had the lowest pre-refit validation output RMSE among the delivered families (`0.07191246` in unspecified `y` units, on all validation trajectories excluding their initial rows), with fewer fitted coefficients than Polynomial and less validation error than ForceClamp. Validation contains overlapping suffixes with training, so this is a comparative diagnostic rather than an independent test claim. All delivered candidates were subsequently refitted on both supplied files. The final TrigSmooth RMSE is `0.04056977` on training and `0.06814319` on validation, both in-sample and in unspecified `y` units. Polynomial provides a nonperiodic restoring alternative; ForceClamp provides a sticking-capable alternative. Near-rest drift and validation-trajectory-specific errors remain; no test result is claimed.'}
json.dump(pool,open('models/pool.json','w'),indent=2)
